insert into public.questions (question_id,paper_id,question_number,question_type,question_points,question_text,option_a,option_b,option_c,option_d,option_e,subject_primary,subsubject_primary,subject_secondary,chapter,topic_primary,topic_secondary,law_refs,tags,source_page_start,source_page_end,extraction_status,review_status,notes,is_published) values
('109-3301-078','109-3301',78,'single_choice',2,'關於家事訴訟程序，下列敘述，何者錯誤？','母再婚後所生子女，母提起確定生父之訴時，應以母之配偶及前配偶為共同被告，若母之配偶或前 配偶有一人死亡者，以生存者為被告','甲對乙請求裁判離婚事件中，若乙抗辯甲、乙結婚不合法定要件而無效，則乙經法院闡明後，得於 同一訴訟提起反訴確認甲、乙婚姻無效而未提起時，不得於離婚訴訟確定後，就同一事由另行提起 確認婚姻無效訴訟','未成年子女為當事人之確認親子關係存在事件，當事人應先釋明足以懷疑有血緣關係之事實，法院 始得依聲請或依職權命當事人或關係人限期接受血緣關係之鑑定','數家事訴訟事件，其請求基礎相牽連者，始得合併請求',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('109-3301-079','109-3301',79,'single_choice',2,'甲夫、乙妻生有未成年子丙、丁，離婚後有關乙請求甲給付贍養費事件之審理程序，下列敘述，何者 正確？','家事法院裁判命甲給付乙贍養費新臺幣（以下同）10 萬元，乙認為金額過少而表示不服，此不服之 事件應由家事法院合議庭審理','乙請求甲一次給付贍養費30 萬元，縱然法院考量乙之情形，認應以每月給付贍養費1 萬元計30 期 為適當，仍應受乙之聲明所拘束','乙請求甲給付贍養費30 萬元，法院僅得依乙提出之證據，審酌乙之請求是否適當','此類事件之審理程序，原則上應準用民事訴訟法之規定',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('109-3301-080','109-3301',80,'single_choice',2,'甲起訴請求判決准其與夫乙離婚，並於判決准許離婚時酌定未成年子女親權之行使由甲任之。關於此 二請求事件，下列敘述，何者正確？','此二事件之本案審理有交錯適用訴訟法理及非訟法理之需要','受理此二請求之家事法院，於認為必要時，得先以本案裁定酌定由甲或乙行使親權，待此項裁定確 定後，始就離婚請求為本案審理','家事法院就此二請求為本案審判時，不得酌定乙為親權行使人，以免逾越甲之聲明範圍','家事法院就此二請求為本案審理後，縱使認為甲及乙均有危害未成年子女之慣行時，亦不得為該子 女選定甲及乙以外之人為監護人',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('109-4301-001','109-4301',1,'single_choice',2,'有關公司法上對公司行為之限制，下列敘述，何者正確？','除公開發行股票公司外，其他公司均得成為合夥事業之合夥人','公開發行股票公司為他公司有限責任股東時，其所有投資總額，不得超過公司實收股本百分之四十， 但得以章程排除此等限制','公司不得為任何保證人，亦不得透過章程排除此等法律限制','除公開發行股票公司外，其他公司均得將資金貸與任何人',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('109-4301-002','109-4301',2,'single_choice',2,'公司法對於公司種類之變更，下列敘述，何者錯誤？','無限公司得經股東三分之二以上之同意變更章程，將其組織變更為有限公司，不同意之股東得以書 面向公司聲明退股','兩合公司得經股東三分之二以上之同意變更章程，將其組織變更為股份有限公司，不同意之股東得 以書面向公司聲明退股','閉鎖性股份有限公司得經股東會特別決議，變更為非閉鎖性股份有限公司','有限公司須經股東表決權三分之二以上之同意，始得變更其組織為股份有限公司',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('109-4301-003','109-4301',3,'single_choice',2,'甲、乙、丙三人擬採取發起設立方式成立X 股份有限公司（下稱X 公司），該公司章程規定「股份總 數為1000 萬股，得分次發行」。下列關於X 公司資本額之說明，何者錯誤？','現行公司法已廢除最低實收資本額制度，對於公司實收資本額無最低要求','X 公司申請設立登記之資本額，應於申請設立登記時或設立登記後三十日內，檢送會計師查核簽 證之文件','X 公司第一次發行股份總數為300 萬股，甲、乙、丙三名發起人需認足之，並得以公司所需財產抵 繳股款','X 公司第一次發行股份總數為300 萬股，甲、乙、丙三人並未實際繳納股款而以申請文件表明收足 者，僅會受到行政罰鍰之處罰',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('109-4301-004','109-4301',4,'single_choice',2,'經理人亦為公司負責人，應遵守相關之義務，下列何者並非公司法明文規定之經理人義務？','不得兼任其他營利事業之經理人','不得自營同類業務','不得為他人經營同類業務','不得為非同類業務事業之無限責任股東',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('109-4301-005','109-4301',5,'single_choice',2,'依公司法規定及實務見解，關於公司舉行股東會採行電子投票制度之敘述，下列何者錯誤？','股東甲以委託書授權他人代理出席後，未撤銷該委託又自為電子投票，以代理人出席行使之表決權 為準','已依電子方法行使表決權之股東乙，即使親自出席股東會亦不得就臨時動議行使表決權','股東丙以電子方式行使表決權後，可於股東會開會二日前撤銷該表決權之意思表示','股東丁以書面或電子方式行使表決權時，其意思表示有重複時，以最先送達者為準',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('109-4301-006','109-4301',6,'single_choice',2,'A 有限公司有股東甲、乙、丙三人，甲、乙為公司之董事，且甲為董事長。今甲個人有一間商業辦公 空間，欲出租給A 公司作為營業處所，該租賃契約應由何人代表A 公司與甲簽訂契約？又A 公司之 董事乙可否單方面無故辭去其董事一職？','該租賃契約應由乙代表A 公司簽訂；又乙基於委任關係得隨時辭去董事職務','該租賃契約應由丙代表A 公司簽訂；又乙基於委任關係得隨時辭去董事職務','該租賃契約應由乙代表A 公司簽訂；又乙不得無故辭去董事職務','該租賃契約應由丙代表A 公司簽訂；又乙不得無故辭去董事職務',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('109-4301-007','109-4301',7,'single_choice',2,'A 股份有限公司係一實收資本額新臺幣（以下同）2000 萬元之非公開發行公司，該公司持有另一家實 收資本額1000 萬元之B 股份有限公司百分之九十二的股權。今A、B 兩家公司擬以吸收合併方式進 行合併，並以A 公司為存續公司。依公司法之規定，下列敘述何者正確？','合併後之A 公司，其資本額依法必須是3000 萬元','A、B 兩公司合併只要經兩家公司董事會特別決議通過即可，無須經股東會決議程序','A 公司股東甲反對兩家公司合併，得請求A 公司按當時公平價格收買其持有之股份','A、B 兩家公司合併後，B 公司為消滅公司，B 公司依法應進行清算',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('109-4301-008','109-4301',8,'single_choice',2,'非公開發行股票且非閉鎖性之A 股份有限公司，欲私募轉換公司債，須經何種程序？','僅須經董事會普通決議','僅須經董事會特別決議','經董事會普通決議，並經股東會普通決議','經董事會特別決議，並經股東會普通決議',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('109-4301-009','109-4301',9,'single_choice',2,'X 股份有限公司（下稱X 公司）為一家非閉鎖性之非公開發行股票公司，擬發行特別股，其特別股之 設計內容，依公司法之規定，下列選項中何者適法？','X 公司擬發行對於特定事項具否決權之特別股，該特別股之設計，得針對「總經理之任用」行使否 決權','X 公司擬就分派股息及紅利之定額或定率，發行特別股，而該定額或定率得為零','X 公司擬發行複數表決權特別股，而該特別股股東，於選舉董事或監察人時，其選舉權之計算得乘 以複數表決權，無須與普通股股東之表決權同','X 公司擬發行無表決權特別股，並禁止該特別股股東出席股東會',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('109-4301-010','109-4301',10,'single_choice',2,'A 公司為一非公開發行公司，其持有B 公開發行公司有表決權股份總數百分之九十，甲係A 公司之 法務長，乙係B 公司之董事長且未於B 公司兼任其他職務。下列關於員工獎酬之敘述，何者正確？','A 公司不能發行限制員工權利新股，B 公司能發行限制員工權利新股給乙','A、B 公司均可以發行限制員工權利新股給甲及乙','B 公司不能發行限制員工權利新股，A 公司能發行限制員工權利新股給甲','A、B 公司均可發行限制員工權利新股給甲',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('109-4301-011','109-4301',11,'single_choice',2,'X 股份有限公司（下稱X 公司）有董事三名甲、乙、丙，三人因涉嫌共謀淘空公司資產而逃亡海外， 致使X 公司之經營陷於癱瘓。監察人丁乃聲請法院選任臨時管理人代行董事會職權，法院則選任戊自 然人與Z 法人擔任此等職務。按在現行公司法下，有關臨時管理人制度之規範，下列敘述，何者錯誤？','戊與Z 在執行臨時管理人職務範圍內，為X 公司負責人','戊與Z 在執行臨時管理人職務時，均應負忠實及注意義務','監察人丁如認為戊與Z 不適任，得聲請法院解任戊與Z 之職務','監察人丁如認為戊與Z 不適任，丁得自行召集股東會，以股東會決議方式解任戊與Z 之職務',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('109-4301-012','109-4301',12,'single_choice',2,'甲、乙、丙3 人均為A 股份有限公司（下稱A 公司）監察人，下列敘述，何者錯誤？','對於通常監察事務之執行，甲、乙、丙各可單獨為之','對重大監察事務之執行，甲、乙、丙有不同意見時，應採多數決決定之','甲、乙、丙皆不得兼任公司董事、經理人或其他職員','甲、乙、丙任期最長為3 年，但得連選連任',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('109-4301-013','109-4301',13,'single_choice',2,'甲、乙、丙3 人共同籌設A 糕餅股份有限公司，經3 人同意並簽名但未蓋章之章程記載A 股份有限 公司每股面額新臺幣（以下同）壹圓，股份總數為100 萬股，全數發行。3 人並同意由乙認股60 萬股 以現金繳納，丙認股40 萬股以經鑑價價值40 萬元之大型電烤箱4 台抵繳，甲則實際執行公司籌設事 務，無須認股出資。前列敘述，何者不符合公司法之規定？','章程雖經甲、乙、丙三人簽名但未蓋章','章程記載股份總數100 萬股，全數發行','丙以大型電烤箱4 台抵繳股款','甲無須認股出資',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('109-4301-014','109-4301',14,'single_choice',2,'A 股份有限公司為非公開發行公司，現有全部資產為新臺幣（以下同）3 億元，其中無形資產 為1.5 億元，負債為1 億元。該公司未曾發行任何公司債，今欲私募有擔保普通公司債，該公司最多 可發行多少數額？','2 億元','0.5 億元','5.5 億元','無上限',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('109-4301-015','109-4301',15,'single_choice',2,'X 股份有限公司（下稱X 公司）與Y 股份有限公司（下稱Y 公司）為控制與從屬公司。Y 公司為調 度資金，除向X 公司借貸新臺幣（以下同）1 億元並以名下土地設定抵押權作為擔保外，另向Z 銀 行借貸2 億元。嗣後，X 公司利用其對Y 公司之支配力，促使Y 公司從事不合營業常規之交易行 為，導致Y 公司受有5 千萬元之損害，不僅如此，Y 公司事業經營均徹底失敗而瀕臨破產。下列敘 述，何者錯誤？','X 公司對於Y 公司所受5 千萬元之損害，應於會計年度終了時先為適當補償，若未為之，則應負 損害賠償責任','X 公司若未對Y 公司賠償5 千萬元，Z 銀行得以自己名義請求X 公司對Y 公司為給付','X 公司不得以對Y 公司之1 億元債權，主張抵銷X 公司對Y 公司應負擔5 千萬元之損害賠償金','X 公司若未對Y 公司賠償5 千萬元，繼續六個月以上持有Y 公司股份之股東，得以自己名義， 請求X 公司對Y 公司為給付',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('109-4301-016','109-4301',16,'single_choice',2,'甲經常在家中抽菸，其子乙恐甲不慎釀成火災，遂以甲之房屋為標的物投保火災保險。下列關於保險 契約效力之敘述，何者正確？','有效','效力未定','無效','得撤銷',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('109-4301-017','109-4301',17,'single_choice',2,'甲以其所有之房屋投保火災保險，嗣後隔鄰工廠發生大火，甲為避免大火延燒己屋採取避免損害措施， 因而支出必要費用新臺幣（以下同）200 萬元，然甲屋仍部分燒燬，損失400 萬元。火災發生時，甲 屋價值1000 萬元（不含土地），保險金額600 萬元。下列關於避免損害費用償還之敘述，何者正確？','不得請求，因甲之行為並非受保險人指示','雖甲屋仍部分毀損，但在保險金額範圍內，甲仍得全額請求所支出之避免損害費用','不得請求，因甲避免損害之行為無效果','甲得依投保比例請求償還所支出之避免損害必要費用',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('109-4301-018','109-4301',18,'single_choice',2,'保險事故發生後，要保人如怠於通知保險人時，保險人得為如何主張？','得依法解除契約','得主張不負保險理賠責任','僅得請求損害賠償','除得解除契約外，並得請求損害賠償',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('109-4301-019','109-4301',19,'single_choice',2,'下列有關特約條款之敘述，何者錯誤？','特約條款以履行不可能或不合法之事項為內容者，保險契約無效','當事人一方違反特約條款時，他方得於除斥期間內解除契約','當事人一方違反特約條款時，他方當事人得於知悉後一個月內解除契約','與保險契約有關之一切事項，不問過去現在或未來，均得以特約條款約定之',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('109-4301-020','109-4301',20,'single_choice',2,'甲以自己為被保險人，向A 保險公司投保人壽保險，於要保書之書面詢問事項刻意隱瞞罹患高血壓 症之事實。契約簽訂六個月後，甲因車禍死亡，A 保險公司於理賠時發現甲隱瞞罹患高血壓症之事實， 依法院實務見解，得否拒絕保險給付？','甲違反保險法第64 條，A 保險公司得解除契約，拒絕給付','甲刻意隱瞞罹患高血壓症，違反誠信原則，A 保險公司得拒絕給付','罹患高血壓症與車禍喪生之保險事故間無因果關係，A 保險公司不得解除契約，仍應負保險給付之責','依一般保險實務，罹患高血壓症為人壽保險之重要詢問事項，A 保險公司應得解除契約，拒絕給付',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('109-4301-021','109-4301',21,'single_choice',2,'甲以其所有之汽車修護工廠投保火災保險，保險人承保之範圍為工廠各項設施及廠內客戶待修車輛之 火災損失。火災事故發生，同時焚燬廠內待修汽車5 部及員工自有汽車3 部。下列關於理賠範圍之敘 述，何者正確？','待修汽車5 部應予理賠，員工自有汽車3 部無須理賠','待修汽車5 部無須理賠，員工自有汽車3 部應予理賠','待修汽車5 部及員工自有汽車3 部均應理賠','待修汽車5 部及員工自有汽車3 部均無須理賠',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('109-4301-022','109-4301',22,'single_choice',2,'甲隱匿其曾經罹患精神疾病之事實，投保健康保險。下列敘述，何者正確？','自契約訂立兩年後，甲因癌症住院，保險人得另以甲隱匿精神疾病為由，解除保險契約','自契約訂立一年時，甲因癌症住院，保險人得於知悉後一個月後另以甲隱匿精神疾病為由，解除保 險契約','自契約訂立兩年後，甲精神疾病再度復發，保險人得以甲隱匿精神疾病為由，解除保險契約','自契約訂立兩年後，甲精神疾病再度復發，保險人亦不得解除契約',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('109-4301-023','109-4301',23,'single_choice',2,'甲以其妻乙為被保險人，與保險人訂立死亡保險契約。下列關於同意權之敘述，何者錯誤？','契約之訂立及保險金額，均應經被保險人書面同意','契約訂立時，受益人之指定應經被保險人書面同意','契約存續期間，受益人之變更得不經被保險人書面承認','契約存續期間，受益人之變更應經被保險人書面承認',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('109-4301-024','109-4301',24,'single_choice',2,'甲以自己為被保險人，與保險人訂立人壽保險契約時，年齡已35 歲，但為減輕保險費之負擔，謊稱 為26 歲。保險契約訂立後，保險人始發現其年齡說明不實，依保險法之規定，保險人得為如何主張？','解除契約','主張契約無效','得請求補繳短繳之保險費或按比例調降保險金額','終止契約',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('109-4301-025','109-4301',25,'single_choice',2,'安定基金由各保險業提撥，其提撥比率，由主管機關審酌經濟、金融發展情形及保險業承擔能力定之， 但提撥額度不得低於各保險業者總保險費收入之比例為何？','百分之一','千分之一','千分之二','萬分之一',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('109-4301-026','109-4301',26,'single_choice',2,'甲向乙購買二手車一部，價金新臺幣30 萬元，甲並簽發以自己為發票人、丙為付款人，一個月後到 期之匯票以支付價款。然該車竟於過戶交車前遭竊，甲因未能取得該車，遂主張解除契約並請求乙返 還該匯票。然乙取得票據後即背書轉讓予善意之丁以償還其欠款，因而向甲表示無法返還該匯票。而 受讓該票之丁又再將該票據贈與其母戊，以祝賀其六十大壽。該票到期後，戊乃持該票向丙請求付款 遭拒，下列敘述何者正確？','因甲、乙間買賣契約已解除，因此戊並不得向甲請求票款','因戊為無償取得該票據，是以無法主張票據權利，無法行使追索權','因丁為善意，是以戊仍取得票據權利，而得向甲行使追索權，甲不得拒絕','戊為無償取得票據，因而不能向背書人乙主張追索權，而只得向發票人請求',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('109-4301-027','109-4301',27,'single_choice',2,'甲簽發一紙金額新臺幣10 萬元之見票即付的無記名本票交給乙，乙搭捷運途中被丙所竊取，丙立即 將之背書轉讓給其善意債務人丁。下列敘述，何者正確？','乙立即通知甲止付的話，則可阻止丁之善意取得','若乙聲請公示催告，於程序開始後，乙得提供擔保，向甲請求票據金額之支付','此本票為無記名本票，所以不能聲請公示催告','此票據未經乙背書，故票據背書不連續，丁無法主張善意取得',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('109-4301-028','109-4301',28,'single_choice',2,'甲簽發本票一紙用以清償對乙欠款，甲於其上填載金額等應記載事項並簽名後，隨即交付給乙，卻漏 未記載發票日與到期日，乙未察覺，又將該票背書轉讓予善意之丙。下列敘述，何者正確？','該本票因未記載發票日與到期日，故視為見票即付','該本票可視為空白授權票據，經填載完成後即可主張權利','因丙為善意，故甲應依票據文義對其負責','該本票因欠缺應記載事項，故甲、乙均得對丙主張票據無效',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('109-4301-029','109-4301',29,'single_choice',2,'甲簽發記名匯票一紙交付乙，票面金額新臺幣（以下同）100 萬元，乙於票據背面簽名背書並附 記：「20 萬元轉讓丙，80 萬元轉讓丁」，以下關於該匯票之敘述，何者正確？','匯票無效','乙負擔保付款責任','乙之背書無效','乙之附記有效',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('109-4301-030','109-4301',30,'single_choice',2,'紡織廠A 公司之本業經營不善，於全球流感疫情嚴重之時，欲轉型為口罩製造商，並承諾提供一定數 量予某電子大廠B 公司。財務不佳之A 公司向不織布廠商C 公司進貨一批，簽發匯票予C 公司，並 由B 公司擔任匯票保證人，惟B 公司僅於匯票上用印而已，未作其他之記載。下列敘述，何者正確？','保證仍屬有效，視為為承兌人保證','保證仍屬有效，視為為發票人保證','未記載保證意旨，不生保證之效力','未載保證年月日，故保證無效',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('109-4301-031','109-4301',31,'single_choice',2,'甲簽發匯票一張，並經乙背書、丙承兌。丙到期不付款，經執票人同意丁為參加付款。惟丁參加付款時 並未記載何人為被參加付款人。該匯票並無參加承兌人或預備付款人，此時應以何人為被參加付款人？','甲','乙','丙','無被參加付款人',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('109-4301-032','109-4301',32,'single_choice',2,'甲簽發以銀行為擔當付款人，到期日為民國102 年12 月1 日之本票一紙予乙，乙於同年月3 日提示 不獲付款，乃檢具本票及退票理由單聲請法院依票據法第123 條裁定後強制執行，可否獲准？','不應准許。本票執票人未遵期提示，對於其前手之發票人喪失追索權','不應准許。本票執票人未遵期提示，對於發票人即喪失付款請求權','應予准許。本票執票人遵期提示，對發票人並不喪失追索權','應予准許。本票執票人雖未遵期提示，但仍得依票據法第123 條裁定後強制執行',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('109-4301-033','109-4301',33,'single_choice',2,'甲偽造乙之印章簽發一張面額新臺幣50 萬元之匯票給不知情之受款人丙，丙背書轉讓與丁，該匯票 被戊所盜，戊偽造丁之印章，背書轉讓給己，己於到期日前再背書轉讓與庚，下列敘述何者正確？','乙之印章蓋在票據上，乙應負發票人之責任，但可控告甲偽造票據','丁之印章蓋在票據上，丁應負背書人責任','己應負背書人之票據責任','甲及戊係真正蓋乙及丁印章之人，故甲及戊應負票據責任',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('109-4301-034','109-4301',34,'single_choice',2,'A 公司簽發面額新臺幣（以下同）110 萬元之支票一紙予B 公司，付款人為C 銀行。A 公司並在支票 正面右上角劃平行線二道，在線內記載D 銀行。C 銀行為B 公司之主要往來銀行，B 公司在D 銀行 並無帳戶，B 公司向C 銀行提示後，C 銀行立即將票款匯入B 公司在C 銀行之帳戶中。下列敘述何 者正確？','平行線記載之位置錯誤，故本件非平行線支票','平行線內不得記載特定銀行，故本件平行線並不合法','本件支票僅能對D 銀行支付，C 銀行之行為已違反票據法之規定，應負損害賠償責任','C 銀行違法對於B 公司付款，可處最高110 萬元之罰鍰',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('109-4301-035','109-4301',35,'single_choice',2,'甲簽發以A 銀行為付款人之支票一紙交付予乙，支票上由A 銀行記載保付字樣並蓋章，其後乙於票 載發票日屆至向A 銀行提示不獲付款，有關乙行使票據權利之消滅時效期間，下列敘述，何者正確？','乙對A 付款請求權有效期間為一年','乙對A 追索權有效期間為一年','乙對A 付款請求權有效期間為三年','乙對A 追索權有效期間為三年',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('109-4301-036','109-4301',36,'single_choice',2,'A 上市公司將於7 月24 日召開例行性董事會，討論公司國內、外長期轉投資事宜，則該非有緊急情 事之例行性董事會的召集通知，最晚應於何日發出？','同年7 月21 日','同年7 月20 日','同年7 月17 日','同年7 月16 日',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('109-4301-037','109-4301',37,'single_choice',2,'A 公司為一家股票在臺灣證券交易所掛牌交易的銀行，目前該公司實收資本額為新臺幣120 億元，且 A 公司設有9 名董事，其中包括甲、乙、丙3 名獨立董事。下列敘述何者錯誤？','A 公司若設有常務董事，則常務董事中至少應有一席獨立董事且不得少於常務董事席次的五分之一','甲、乙、丙3 名獨立董事執行業務認有必要時，得要求董事會指派相關人員或自行聘請專家協助辦 理，相關必要費用，由A 公司負擔之','A 公司得擇一設置審計委員會或監察人','A 公司應設置薪資報酬委員會',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('109-4301-038','109-4301',38,'single_choice',2,'自然人甲與A 公開發行公司（下稱A 公司）均為B 公開發行公司（下稱B 公司）之股東。甲及A 公司 均當選為B 公司董事，A 公司並指派自然人乙為其法人董事代表人，代表行使職務。下列何者所持有 B 公司股票持股轉讓，不致因該身分關係而受到證券交易法第22 條之2 股權轉讓方式規定的限制？','甲之妻','甲之成年兒子','乙','乙之妻',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('109-4301-039','109-4301',39,'single_choice',2,'非公開發行股票之A 公司已持有B 上櫃公司（下稱B 公司）已發行有表決權股份百分之五十二，其 擬簡易併購B 公司，因此，決定加碼在一個月內再投資買進B 公司有表決權股份百分之三十八。下 列敘述，何者正確？','A 公司可選擇用公開收購或在櫃檯買賣市場買進B 公司股份','A 公司公開收購B 公司股份時，須先向金融監督管理委員會申報','若A 公司公開收購B 公司股份，在公開收購期間，A 公司之從屬公司不能於櫃檯買賣市場買進B 公司股份，但公開收購期間屆滿日後則不受限制','A 公司若採公開收購，在公開收購期間未屆滿前，若應募股數已達百分之三十八，A 公司即應提前 停止公開收購',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('109-4301-040','109-4301',40,'single_choice',2,'已發行普通股600 萬股之A 公開發行股票公司於股東會議決可轉換公司債之私募案，在本次股東會， 出席股東之表決權數合計為510 萬，則最少應有多少表決權同意，本私募案方決議通過？','255 萬','255 萬零1','340 萬','340 萬零1',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('109-4301-041','109-4301',41,'single_choice',2,'A 上櫃公司已發行股份1 億股，為進行海外轉投資所需，董事會決議現金發行新股3000 萬股，新股 的百分之十保留由員工承購，提撥百分之十對外公開發行，股東甲目前持有10 萬股，則甲依股東身 分可被分配認購多少股？','無優先認股權利，由董事會決議定之','2 萬4 千股','3 萬股','8 萬股',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('109-4301-042','109-4301',42,'single_choice',2,'甲多年來持有A 上市公司股票1 萬股及B 上櫃公司股票2 萬股，因近日股市長紅，甲小有獲利，擬 將所持有之A、B 二家公司股票全數直接賣給同事乙。如甲並非A、B 二家公司之董事、監察人及經 理人，亦非為此等人持股之人，就本件甲、乙間讓受A、B 二家公司股票之行為，依證券交易法之規 定，下列敘述何者正確？','本件讓受A、B 二家公司股票之行為均合法','本件讓受A 公司股票之行為合法、讓受B 公司股票之行為違法','本件讓受A 公司股票之行為違法、讓受B 公司股票之行為合法','本件讓受A、B 二家公司股票之行為均違法',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('109-4301-043','109-4301',43,'single_choice',2,'A 上櫃公司（下稱A 公司）已發行股份1000 萬股，先前為配合可轉換公司債之發行，作為股權轉換 之用，A 公司已買回自己公司股份40 萬股，現在A 公司為激勵員工，預計再從櫃檯買賣市場買回公 司股份，假設收買股份之總金額不會超過法定上限情況下，下列敘述何者正確？','A 公司本次最多可買回10 萬股','A 公司本次買回之股份，應於買回之日起五年內將其轉讓','A 公司買回之股份在未轉讓前不得行使表決權，但可參與公司之盈餘分配','A 公司僅得於櫃檯買賣市場進行股份買回',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('109-4301-044','109-4301',44,'single_choice',2,'A 股份有限公司（下稱A 公司）擬發行新股2000 萬股，職員甲於公開說明書虛增應收帳款新臺幣（以 下同）5000 萬元，會計師乙因相信A 公司過去往來信用良好即予簽證認可，最後交由承銷商丙承銷。 投資人丁以每股20 元認購該新股100 萬股，三個月後因公開說明書不實一事被揭露，股票下跌至每 股10 元。下列何人應對丁之損害負無過失之損害賠償責任？','A 公司','職員甲','會計師乙','承銷商丙',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('109-4301-045','109-4301',45,'single_choice',2,'A 上市公司董事長甲於2018 年1 月2 日買進可轉換公司債10 張（可轉換為普通股1 萬股），當日普 通股收盤價新臺幣（以下同）80 元，同年2 月2 日賣出A 公司認售權證1 萬股，當日普通股收盤價 90 元，3 月2 日賣出普通股股票10 張，平均賣價每股100 元，4 月2 日賣出普通股股票10 張，平均 賣價每股105 元，本案依現行法令，在不加計股息、法定利息，及未扣除交易手續費、證券交易稅的 前提下，甲應歸入A 公司之利益為多少？','0 元','10 萬元','25 萬元','35 萬元',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('109-4301-046','109-4301',46,'single_choice',2,'甲持命乙給付金錢之確定判決為執行名義，聲請執行法院查封乙所占用未辦理保存登記之A 屋。下 列敘述，何者錯誤？','如A 屋係丙出資興建，則丙得對本件執行提起第三人異議之訴','如A 屋係丙出資興建，並出售於乙，則丙對本件執行亦得提起第三人異議之訴','如A 屋係丙出資興建，並出售於丁，則丁得代位丙提起第三人異議之訴','如A 屋係丙出資興建，出售於乙，乙再出售於丁，則丁不得代位丙提起第三人異議之訴',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('109-4301-047','109-4301',47,'single_choice',2,'甲依第一審法院判決之假執行宣告，供擔保後聲請對乙強制執行，請求拆除A 屋交還B 地（下稱前 案執行）。乙對該判決提起上訴，另對前案執行亦提起債務人異議之訴，並依異議之訴之受訴法院所 為裁定，供擔保後停止前案執行。3 個月後，第二審法院判決駁回乙對該判決之上訴而告確定。甲再 以該確定之一審判決聲請對乙強制執行，請求拆除A 屋交還B 地（下稱後案執行）。下列敘述，何者 正確？','宣告假執行之判決已確定，執行法院應駁回前案執行聲請','甲就相同請求內容重複聲請強制執行，執行法院應駁回後案執行聲請','前案執行已經乙供擔保後停止執行，後案執行亦當然停止','執行法院仍應實施後案執行',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('109-4301-048','109-4301',48,'single_choice',2,'有關動產之拍賣，下列敘述，何者錯誤？','原則上無須進行鑑價','原則上無須於拍賣前預定底價','如預定底價者，應於拍賣公告上載明','執行法院未通知債權人、債務人於拍賣日到場，而拍賣程序已終結時，拍賣仍有效',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('109-4301-049','109-4301',49,'single_choice',2,'債權人甲持命債務人乙給付金錢之確定支付命令為執行名義，聲請法院強制執行乙在丙公司之薪資債 權。下列敘述，何者錯誤？','乙得以支付命令並未對其合法送達為由，聲明異議','法院對該薪資債權發扣押命令，該命令應對丙及乙送達，但於送達丙時始發生扣押之效力','法院發移轉命令，將乙對丙之部分薪資債權移轉於甲，縱甲之執行債權未能即時全部受償，惟因將 來仍可繼續受償至全部債權獲償為止，故甲之執行程序於法院所發移轉命令生效後，即已終結','丙如否認乙對其有薪資債權，得於接受扣押命令後10 日內，向法院聲明異議',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('109-4301-050','109-4301',50,'single_choice',2,'金錢債權人甲聲請強制執行債務人乙所有之A 屋。下列何種情形，法院不得為「點交」？','A 屋為乙自住','A 屋為第三人丙於查封前向乙承租而占用','A 屋為第三人丁於查封後向乙承租而占用','A 屋經乙作為倉儲使用，自查封前即由乙之保全人員戊管理',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('109-4301-051','109-4301',51,'single_choice',2,'金錢債權人甲聲請執行法院強制執行債務人乙對第三人丙之租金債權。下列敘述，何者正確？','丙收受扣押命令後聲明異議，否認乙對丙之債權存在，經執行法院將丙之異議通知甲，甲如未於收 受通知後10 日內對丙提起確認乙對丙債權存在之訴訟時，則該扣押命令當然失效','丙收受扣押命令後未於10 日內聲明異議，執行法院續發收取命令，丙仍得於收受該收取命令後10 日內聲明異議，執行法院尚不得逕對丙之財產為強制執行','丙收受扣押命令後，如聲明異議稱：乙對丙之債權附有條件且條件尚未成就等語，則執行命令不生 扣押效力','執行法院之扣押命令效力僅及於扣押命令到達丙時已屆期之租金債權',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('109-4301-052','109-4301',52,'single_choice',2,'債權人甲持命債務人乙返還A 地之確定判決為執行名義，聲請執行法院對乙為強制執行。執行法院 會同兩造現場勘驗結果，始知乙於該確定判決最後事實審言詞辯論終結後興建B 建物。甲併聲請執行 法院拆除B 建物，執行法院應如何處理？','拆除B 建物非上開確定判決之效力所及，執行法院應駁回甲併為執行之聲請','B 建物無法與A 地分離，A 地返還部分因而執行不能，執行法院應駁回甲之全部強制執行聲請','確定判決係命乙返還土地，其執行力之客觀範圍及於強制執行時乙在A 地上有處分權之B 建物， 執行法院應依甲之聲請，為拆除B 建物、返還A 地之強制執行','B 建物興建於上開確定判決最後事實審言詞辯論終結之後，執行法院應指示甲另行取得拆除B 建 物之執行名義，並在取得之前停止全部執行程序',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('109-4301-053','109-4301',53,'single_choice',2,'甲訴請乙拆除A 地上之B 屋，並將A 地返還予甲及其他共有人丙，經法院判決甲勝訴並告確定。甲 持該判決聲請強制執行，下列敘述，何者正確？','甲應協同丙聲請強制執行，始為適格之執行當事人','執行標的價額應按B 屋之交易價格核定之','甲因故不擬繼續執行時，得聲請法院核發債權憑證，日後得持債權憑證聲請執行，無庸再繳納執行費','執行法院將B 屋拆除、點交A 地予甲占有後，乙復即占有A 地，甲得持原確定判決再聲請強制執 行，惟應另行繳納執行費',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('109-4301-054','109-4301',54,'single_choice',2,'債權人甲於民國109 年4 月1 日，收受法院准許對於債務人乙之財產在新臺幣（以下同）500 萬元之 範圍內為假扣押之裁定，旋於同年月10 日向執行法院聲請假扣押執行乙在金融機構之200 萬元存款 債權。甲於109 年6 月5 日又聲請對乙所有之A 地為追加假扣押執行。下列敘述，何者正確？','執行法院應准許甲之追加執行聲請','執行法院應駁回甲之追加執行聲請','是否准許甲之追加執行，由執行法院裁量決定','如A 地價值超過300 萬元，執行法院應駁回甲之追加執行聲請',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('109-4301-055','109-4301',55,'single_choice',2,'金錢債權人甲以確定判決為執行名義，就債務人乙所有之A 屋聲請強制執行（前案），第三人丙主張 其為A 屋真正所有權人，對甲提起第三人異議之訴，法院裁定丙提供擔保後停止前案之執行。嗣後乙 之金錢債權人丁就A 屋聲請強制執行（後案），執行法院將前、後案合併，丁聲請繼續執行。下列敘 述，何者正確？','執行法院應待前案執行恢復時，再與後案合併執行','執行法院應不待前案執行恢復，依丁之聲請繼續執行後案','丁聲請後案執行，毋須繳納執行費','甲之前案執行停止，不得由後案執行受分配',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('109-4301-056','109-4301',56,'single_choice',2,'While negligence law most often imposes liability on the basis of individual “fault,” the concept of has held some people responsible for the injuries negligently caused by others.','current liability','vicarious liability','contingent liability','joint and several liability',null,'法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
