('110-2301-017','110-2301',17,'single_choice',2,'有關司法獨立之敘述，下列何者正確？','司法院之年度司法概算，由司法院直接提送立法院審議','大法官皆受終身職待遇之保障','法官非依法律不得減俸','司法院概不得就審理事項發布規則',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
